KG42.register("rules-3762cf35a9d6d5299e219202",{"id":"38-bidirectional_ev_trading::v141-c-R001","paper":"38-bidirectional_ev_trading","record":{"rule_id":"v141-c-R001","mechanism_id":"M01","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"Wholesale price-function information provides an input to customers' sequential social-welfare scheduling updates. The aggregator can broadcast that information together with other customers' aggregate energy consumption. Scope: Sequential distributed solution of the collaborative scheduling problem using customer subproblems P1_i. Condition: At each iteration; the information can be broadcast at the beginning of the iteration. The common-linear-rate distributed formulation represents the collaborative social-welfare-optimal schedule as a collection of customer-optimal schedules at the specified rates. Scope: Proposition 1's distributed linear-billing representation of the collaborative optimum, applying common time-slot rates to all customers. Condition: Electricity rates equal marginal total cost evaluated at the social-welfare-optimal aggregate consumption, as specified in (9). Collaborative scheduling maximizes the sum of all customers' utilities minus the total cost charged to the aggregator, subject to each customer's feasible scheduling set satisfying conditions (1), (2), (3), and (5). Scope: Collaborative power system, all customers, over the scheduling interval. Condition: All customers are willing to cooperate.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.social_welfare","coordination.price_signal"],"E":[{"edge_id":"v141-c-R001-E001","source":"coordination.price_signal","target":"clearing.social_welfare","type":"links","constraint_ids":["v141-c-R001-C001","v141-c-R001-C002"],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E12","v141-b-g01-E13","v141-b-g01-E14","v141-b-g02-e04"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Collaborative power system, all customers, over the scheduling interval. | Proposition 1's distributed linear-billing representation of the collaborative optimum, applying common time-slot rates to all customers. | Sequential distributed solution of the collaborative scheduling problem using customer subproblems P1_i.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E12","v141-b-g01-E13","v141-b-g01-E14","v141-b-g02-e04"]},"x":[{"variable_id":"v141-c-R001-x-app","symbol":"x_{i,App}^t","meaning":"Energy consumed by customer i's residential appliances during time-slot t.","kind":"operational","domain":"Real-valued energy quantity constrained by x_{i,App}^{min,t} \u003c= x_{i,App}^t \u003c= x_{i,App}^{max,t} and by the customer's feasible set X_i.","unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E04","v141-b-g01-E10"]},{"variable_id":"v141-c-R001-x-tot","symbol":"x_{i,Tot}^t","meaning":"Total energy consumption of customer i during time-slot t, including residential appliances and the EV; negative values correspond to energy sold to the aggregator.","kind":"operational","domain":"Real-valued energy quantity constrained by (2)-(3), (5), and X_i; may be negative when a Type III EV sells stored energy.","unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E03","v141-b-g01-E04","v141-b-g01-E10"]},{"variable_id":"v141-c-R001-x-pi","symbol":"\\pi^{*,t}","meaning":"Common linear electricity rate for time-slot t, set equal to marginal total cost evaluated at the social-welfare-optimal aggregate consumption.","kind":"operational","domain":"Real-valued rate given by equation (9) at the social-welfare optimum.","unit":"$/kWh","indices":["t"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E14"]}],"theta":[{"parameter_id":"v141-c-R001-theta-U","symbol":"U_i^t(\\cdot)","meaning":"Customer i's increasing concave utility function for residential appliance energy consumption during time-slot t.","value":{"kind":"symbolic","number_value":null,"text_value":"increasing concave function"},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E10"]},{"parameter_id":"v141-c-R001-theta-C","symbol":"C^t(\\cdot)","meaning":"Aggregator's total cost at time-slot t as a function of total customer energy consumption.","value":{"kind":"symbolic","number_value":null,"text_value":"C^t(z)=p^t(z)z"},"unit":"$","indices":["t"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10","v141-b-g01-E13"]},{"parameter_id":"v141-c-R001-theta-p","symbol":"p^t(\\cdot)","meaning":"Linear wholesale electricity price per unit energy as a function of total system demand, predetermined by the utility company.","value":{"kind":"symbolic","number_value":null,"text_value":"p^t(Q)=a^t Q+b^t; a^t>0, b^t>0"},"unit":"$/kWh","indices":["t"],"evidence_ids":["v141-b-g01-E07","v141-b-g02-e04"]},{"parameter_id":"v141-c-R001-theta-a","symbol":"a^t","meaning":"Time-varying positive slope coefficient of the linear wholesale price function.","value":{"kind":"symbolic","number_value":null,"text_value":"positive time-varying coefficient predetermined by the utility company"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E13"]},{"parameter_id":"v141-c-R001-theta-b","symbol":"b^t","meaning":"Time-varying positive intercept coefficient of the linear wholesale price function.","value":{"kind":"symbolic","number_value":null,"text_value":"positive time-varying coefficient predetermined by the utility company"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E13"]}],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"Wholesale price-function information provides an input to customers' sequential social-welfare scheduling updates. The aggregator can broadcast that information together with other customers' aggregate energy consumption. Scope: Sequential distributed solution of the collaborative scheduling problem using customer subproblems P1_i. Condition: At each iteration; the information can be broadcast at the beginning of the iteration.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","clearing.social_welfare"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E12","v141-b-g02-e04"]},{"constraint_id":"v141-c-R001-C002","kind":"mathematical","role":"core","statement":"The common-linear-rate distributed formulation represents the collaborative social-welfare-optimal schedule as a collection of customer-optimal schedules at the specified rates. Scope: Proposition 1's distributed linear-billing representation of the collaborative optimum, applying common time-slot rates to all customers. Condition: Electricity rates equal marginal total cost evaluated at the social-welfare-optimal aggregate consumption, as specified in (9).","expression":"P2_i:\\ \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*,t}x_{i,Tot}^t\\quad \\text{s.t. }\\bar{x}_i\\in X_i,\\quad \\pi^{*,t}=C'^t\\left(\\sum_{i\\in I}x_{i,Tot}^{*,t}\\right)=2a^t\\sum_{i\\in I}x_{i,Tot}^{*,t}+b^t,\\ \\forall t\\in T","formalization_origin":"source","template_id":null,"members":["coordination.price_signal","clearing.social_welfare"],"variable_refs":["v141-c-R001-x-app","v141-c-R001-x-tot","v141-c-R001-x-pi"],"parameter_refs":["v141-c-R001-theta-U","v141-c-R001-theta-C","v141-c-R001-theta-a","v141-c-R001-theta-b"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E14"]},{"constraint_id":"v141-c-R001-C003","kind":"mathematical","role":"core","statement":"Collaborative scheduling maximizes the sum of all customers' utilities minus the total cost charged to the aggregator, subject to each customer's feasible scheduling set satisfying conditions (1), (2), (3), and (5). Scope: Collaborative power system, all customers, over the scheduling interval. Condition: All customers are willing to cooperate.","expression":"\\max_{\\bar{x}} \\sum_{t\\in T}\\sum_{i\\in I}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t\\left(\\sum_{i\\in I}x_{i,Tot}^t\\right)\\quad \\text{s.t. }\\bar{x}_i\\in X_i,\\ \\forall i\\in I","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R001-x-app","v141-c-R001-x-tot"],"parameter_refs":["v141-c-R001-theta-U","v141-c-R001-theta-C"],"evidence_ids":["v141-b-g01-E10"]},{"constraint_id":"v141-c-R001-C004","kind":"mathematical","role":"supporting","statement":"The aggregator's total cost at time-slot t is the linear wholesale price evaluated at total customer energy consumption multiplied by total customer energy consumption; the wholesale price function is linear in total demand with positive time-varying coefficients.","expression":"C^t\\left(\\sum_{i\\in I}x_{i,Tot}^t\\right)=p^t\\left(\\sum_{i\\in I}x_{i,Tot}^t\\right)\\times\\sum_{i\\in I}x_{i,Tot}^t,\\quad p^t\\left(\\sum_{i\\in I}x_{i,Tot}^t\\right)=a^t\\sum_{i\\in I}x_{i,Tot}^t+b^t,\\quad a^t>0,\\ b^t>0,\\ \\forall t\\in T","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R001-x-tot"],"parameter_refs":["v141-c-R001-theta-C","v141-c-R001-theta-p","v141-c-R001-theta-a","v141-c-R001-theta-b"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E09"]}],"pi":[{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-54c42059a7-p04-c1r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"cooperate to maximize the social welfare of the system, which anis deﬁned as the sum of all customer","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"In this section, we study the energy scheduling problem for a collaborative system, where all customers are willing to cooperate to maximize the social welfare of the system, which is defined as the sum of all customers' utilities minus the total cost charged to the aggregator. The resulting social welfare serves an upper bound on social welfare obtained using any feasible approaches. We first consider the following social welfare maximization problem: P: \\max_{\\bar{x}} \\sum_{t\\in T}\\sum_{i\\in I}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^t) s.t. \\bar{x}_i\\in X_i, \\forall i\\in I, where X_i represents the feasible set of customer i's energy scheduling which is defined as a set of \\bar{x}_i's that satisfy conditions in (1),(2),(3), and (5). It can be easily shown that problem P is convex programming. Moreover, the objective function is strictly concave with respect to \\bar{x}_i, the scheduling decision of any customer i, when the other customers' scheduling decisions, \\bar{x}_{-i}=[\\bar{x}_{i'}]_{i'\\ne i}, are fixed. Due to these properties of problem P, we can use the Gauss-Seidel method to solve it [22]."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-54c42059a7-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of where Xt,(k+1)−i = i′\u003ci xt,(k+1)i′,T ot + i′>i xt,(k)i′,T ot. Problem sh P1i is a convex optimiza","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"At each iteration k+1, customers update there energy scheduling decisions, \\bar{x}_i^{(k+1)}, sequentially by solving the following problem: P1_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t(x_{i,Tot}^t+X_{-i}^{t,(k+1)}) s.t. \\bar{x}_i\\in X_i, where X_{-i}^{t,(k+1)}=\\sum_{i'\u003ci}x_{i',Tot}^{t,(k+1)}+\\sum_{i'>i}x_{i',Tot}^{t,(k)}. Problem P1_i is a convex optimization problem and can be solved by using standard algorithms for convex optimization."},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-54c42059a7-p04-c2r1__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"JOURNAL ON SELECTED AREAS IN COMMUNICATIONS, VOL. 31, NO. 7, JULY 2013 we following problem: as P2i ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Proposition 1. The optimal solution of problem P, \\bar{x}^*, can be represented as the collection of optimal solutions of the following problem: P2_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*t}x_{i,Tot}^t s.t. \\bar{x}_i\\in X_i, where \\bar{\\pi}^*=[\\pi^{*t}]_{t\\in T} is given as \\pi^{*t}=C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})=2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t, \\forall t\\in T, (9) and function C'^t(z) denotes the first derivative of the total cost function C^t(z) with respect to z. Proof: See Appendix."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-54c42059a7-p04-c2r2__v141-a-M01-settlement","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"ch and function C ′t(z) denotes the ﬁrst derivative of the totaltal cost function Ct(z) with respect","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot."},{"evidence_id":"v141-b-g02-e04","location":{"location_id":"src-54c42059a7-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"1222","section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of where Xt,(k+1)−i = i′\u003ci xt,(k+1)i′,T ot + i′>i xt,(k)i′,T ot. Problem sh P1i is a convex optimiza","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Note that at each iteration, each customer needs to acquire only the information about the wholesale price function p^t(\\cdot), \\forall t\\in T and the sum energy consumption of other customers, X_{-i}^{t,(k+1)}, \\forall t\\in T. Such information can be updated and broadcast by the aggregator through the communication with the customer's ECS at the beging of each iteration."},{"evidence_id":"v141-b-g01-E02","location":{"location_id":"src-54c42059a7-p03-c1r3__v141-a-M01-clearing","page":3,"printed_page":null,"section":"II. System Model","anchor_text":", pp tial appliances, xti,App. Compared to residential appliances that only consume energy, the EV h","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"focusing on the energy trading among customers, we consider a simplified appliance model where the amount of energy consumed by all the residential appliances of customer i during time-slot t is denoted by a single variable x_{i,App}^t. Then, we model customer i's utility function for its residential appliances during time-slot t as an increasing concave function U_i^t(x_{i,App}^t) of the amount of energy consumed by the residential appliances, x_{i,App}^t. Compared to residential appliances that only consume energy, the EV has the capability to charge and discharge energy into/from its built-in battery. The discharged energy can be used by other appliances, and thus x_{i,App}^t includes the energy consumed from the battery in the EV as well as the aggregator. We denote the total amount of customer i's energy consumption during time-slot t by x_{i,Tot}^t with the inclusion of the energy consumed by both the residential appliances and the EV. Accordingly, the difference between x_{i,Tot}^t and x_{i,App}^t, i.e., x_{i,Tot}^t - x_{i,App}^t, is the amount of energy charged/discharged into/from the EV's battery during time-slot t. Positive difference, x_{i,Tot}^t - x_{i,App}^t > 0, represents that the corresponding amount of energy is charged to the EV's battery during time-slot t, while negative difference, x_{i,Tot}^t - x_{i,App}^t \u003c 0, represents that the corresponding amount of energy is discharged from the EV's battery. We denote the overall energy scheduling of customer i by \\bar{x} = [\\bar{x}_i]_{i\\in I}, where \\bar{x}_i = [x_{i,Tot}^t, x_{i,App}^t]_{t\\in T}."},{"evidence_id":"v141-b-g01-E03","location":{"location_id":"src-54c42059a7-p03-c1r4__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. System Model","anchor_text":"overall energy scheduling of customer i by x = [xi]i∈I, where tri ¯xi = [xti,T ot, xti,App]t∈T . ch ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"We allow the bidirectional energy trading between customers and the aggregator, i.e., each customer can sell its energy to the aggregator when it has surplus energy stored in its EV's battery. Due to the energy trading capability, x_{i,Tot}^t may have a negative value, which means that the corresponding amount of energy is sold to the aggregator. For example, if x_{i,App}^t = 5 kWh and x_{i,Tot}^t = -10 kWh (accordingly x_{i,Tot}^t - x_{i,App}^t = -15 kWh), customer i discharges 15 kWh of energy from its battery to use 5 kWh for its own appliances and to sell 10 kWh to the aggregator at t-th time-slot."},{"evidence_id":"v141-b-g01-E04","location":{"location_id":"src-54c42059a7-p03-c2r1__v141-a-M01-clearing","page":3,"printed_page":null,"section":"II. System Model","anchor_text":"SCHEDULING WITH ELECTRIC VEHICLES IN THE SMART GRID 1221 both maximum and minimum amounts of energy ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"both maximum and minimum amounts of energy which the residential appliances and the customer i's household can consume during each time-slot, i.e., x_{i,App}^{min,t} \\le x_{i,App}^t \\le x_{i,App}^{max,t}, \\forall t\\in T (1) x_{i,Tot}^{min,t} \\le x_{i,Tot}^t \\le x_{i,Tot}^{max,t}, \\forall t\\in T. (2) The amount of charged (or discharged) energy of the EV during each time-slot is also constrained by the maximum and minimum values, i.e., x_{i,EV}^{min,t} \\le x_{i,Tot}^t - x_{i,App}^t \\le x_{i,EV}^{max,t}, \\forall t\\in T. (3)"},{"evidence_id":"v141-b-g01-E07","location":{"location_id":"src-54c42059a7-p03-c2r4__v141-a-M01-clearing","page":3,"printed_page":null,"section":"II. System Model","anchor_text":"re 2 tricity market as illustrated in Fig. 1. The utility company charges the aggregator an electric","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"For each time-slot, the aggregator buys electricity, which corresponds to the total demand of the power system, \\sum_{i\\in I}x_{i,Tot}^t, from the utility company in the wholesale electricity market as illustrated in Fig. 1. The utility company charges the aggregator an electricity cost based on a linear wholesale electricity price function per unit energy [21], which is given by p^t(\\sum_{i\\in I}x_{i,Tot}^t)=a^t\\sum_{i\\in I}x_{i,Tot}^t+b^t, \\forall t\\in T, (6) where a^t>0 and b^t>0 may vary in time and are predetermined by the utility company before the scheduling interval."},{"evidence_id":"v141-b-g01-E09","location":{"location_id":"src-54c42059a7-p04-c1r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"1222 IEEE JOURNAL system increases, the wholesale price also increases. Then, we fol can represent t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"system increases, the wholesale price also increases. Then, we can represent the total cost of the aggregator at time-slot t as C^t(\\sum_{i\\in I}x_{i,Tot}^t)=p^t(\\sum_{i\\in I}x_{i,Tot}^t)\\times\\sum_{i\\in I}x_{i,Tot}^t, \\forall t\\in T. (7)"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing","v141-a-M01-settlement"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e04","quote":"Note that at each iteration, each customer needs to acquire only the information about the wholesale price function p^t(\\cdot), \\forall t\\in T and the sum energy consumption of other customers, X_{-i}^{t,(k+1)}, \\forall t\\in T. Such information can be updated and broadcast by the aggregator through the communication with the customer's ECS at the beging of each iteration."},{"evidence_id":"v141-b-g01-E12","quote":"At each iteration k+1, customers update there energy scheduling decisions, \\bar{x}_i^{(k+1)}, sequentially by solving the following problem: P1_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t(x_{i,Tot}^t+X_{-i}^{t,(k+1)}) s.t. \\bar{x}_i\\in X_i"},{"evidence_id":"v141-b-g01-E10","quote":"In this section, we study the energy scheduling problem for a collaborative system, where all customers are willing to cooperate to maximize the social welfare of the system, which is defined as the sum of all customers' utilities minus the total cost charged to the aggregator."}],[{"evidence_id":"v141-b-g01-E13","quote":"Proposition 1. The optimal solution of problem P, \\bar{x}^*, can be represented as the collection of optimal solutions of the following problem: P2_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*t}x_{i,Tot}^t s.t. \\bar{x}_i\\in X_i, where \\bar{\\pi}^*=[\\pi^{*t}]_{t\\in T} is given as \\pi^{*t}=C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})=2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t, \\forall t\\in T, (9)"},{"evidence_id":"v141-b-g01-E14","quote":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i."}],[{"evidence_id":"v141-b-g01-E10","quote":"In this section, we study the energy scheduling problem for a collaborative system, where all customers are willing to cooperate to maximize the social welfare of the system, which is defined as the sum of all customers' utilities minus the total cost charged to the aggregator."},{"evidence_id":"v141-b-g01-E10","quote":"s.t. \\bar{x}_i\\in X_i, \\forall i\\in I, where X_i represents the feasible set of customer i's energy scheduling which is defined as a set of \\bar{x}_i's that satisfy conditions in (1),(2),(3), and (5)."}]],"C2_formalization":{"graph_sha256":"1fa740dac44cff952e1ca51b4bd6df10224fc348da5bf33614cb179acf97b3e1","applicability":"formalized","reason":"Formalized from the explicit social-welfare problem P, the customer decomposition P2_i with the common linear rate (9), and the wholesale cost/price definitions (6)-(7). C001 is retained as procedural because it specifies an information-broadcast step rather than an additional optimization formula. Evidence IDs are unreviewed candidate support under the experiment policy; no independent B-source audit or scientific acceptance is claimed.","bindings":[{"object_id":"v141-c-R001-C001","node_ids":["coordination.price_signal","clearing.social_welfare"],"edge_ids":["v141-c-R001-E001"],"rationale":"C001 is the procedural information-exchange rule connecting the price-function broadcast to social-welfare scheduling; edge E001 is the frozen relation between the two nodes."},{"object_id":"v141-c-R001-C002","node_ids":["coordination.price_signal","clearing.social_welfare"],"edge_ids":["v141-c-R001-E001"],"rationale":"Proposition 1 decomposes the welfare optimum into customer problems P2_i using the common rate; edge E001 records the price-signal-to-welfare relationship."},{"object_id":"v141-c-R001-C003","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Problem P defines the social-welfare objective maximized over customer schedules; no price-signal edge is needed for the definition itself."},{"object_id":"v141-c-R001-C004","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Equations (6)-(7) define the wholesale price and aggregator cost term used in P; the frozen graph has no separate wholesale-cost node, so this attaches to social-welfare clearing."},{"object_id":"v141-c-R001-x-app","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Appliance energy is a decision argument in both the social-welfare objective P and the customer problem P2_i."},{"object_id":"v141-c-R001-x-tot","node_ids":["clearing.social_welfare","coordination.price_signal"],"edge_ids":["v141-c-R001-E001"],"rationale":"Total energy enters both the welfare cost term and the common rate (9) through aggregate consumption; edge E001 records the price-signal-to-welfare relationship."},{"object_id":"v141-c-R001-x-pi","node_ids":["coordination.price_signal","clearing.social_welfare"],"edge_ids":["v141-c-R001-E001"],"rationale":"The common rate is the price signal in Proposition 1, formed from the social-welfare-optimal aggregate consumption; edge E001 links the signal to welfare clearing."},{"object_id":"v141-c-R001-theta-U","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The utility function supplies the welfare benefit term in P and P2_i."},{"object_id":"v141-c-R001-theta-C","node_ids":["clearing.social_welfare","coordination.price_signal"],"edge_ids":["v141-c-R001-E001"],"rationale":"Total cost supplies the welfare cost term, and its derivative defines the common linear rate; edge E001 links the rate to the welfare optimum."},{"object_id":"v141-c-R001-theta-p","node_ids":["coordination.price_signal","clearing.social_welfare"],"edge_ids":["v141-c-R001-E001"],"rationale":"The wholesale price function is the price-function information broadcast in C001 and underlies both total cost and the optimal rate."},{"object_id":"v141-c-R001-theta-a","node_ids":["clearing.social_welfare","coordination.price_signal"],"edge_ids":["v141-c-R001-E001"],"rationale":"The coefficient a^t appears in the wholesale price function and in the optimal linear rate (9), linking price signal and welfare clearing."},{"object_id":"v141-c-R001-theta-b","node_ids":["clearing.social_welfare","coordination.price_signal"],"edge_ids":["v141-c-R001-E001"],"rationale":"The coefficient b^t appears in the wholesale price function and in the optimal linear rate (9), linking price signal and welfare clearing."}],"revision_requests":[]}},"quarantined_references":[]}});
